import java.io.{File, FileInputStream, BufferedInputStream}
import java.nio.file.{Files, Paths, Path}
import java.security.MessageDigest
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

object UploadProcessor {

  case class UploadMetadata(
    filename: String,
    contentType: String,
    size: Long,
    checksum: String
  )

  private val ALLOWED_EXTENSIONS = Set(".csv", ".json", ".xml", ".txt")
  private val MAX_FILE_SIZE = 10 * 1024 * 1024L // 10MB
  private val UPLOAD_DIR = "/var/uploads/staging"
  private val PROCESSED_DIR = "/var/uploads/processed"
  private val ALLOWED_FILENAME_PATTERN = "^[a-zA-Z0-9][a-zA-Z0-9._-]{0,99}$".r

  private val processingChain = mutable.LinkedHashMap[String, UploadMetadata => Either[String, Path]](
    "validate" -> validateUpload,
    "scan" -> scanForMalware,
    "transform" -> transformContent,
    "archive" -> archiveProcessed
  )

  def main(args: Array[String]): Unit = {
    if (args.length < 1) {
      System.err.println("Usage: UploadProcessor <upload-manifest-path>")
      System.exit(1)
    }
    val manifestPath = args(0)
    val entries = parseManifest(manifestPath)
    entries.foreach(processEntry)
  }

  private def parseManifest(path: String): Seq[UploadMetadata] = {
    val lines = scala.io.Source.fromFile(path).getLines().toSeq
    lines.flatMap { line =>
      val parts = line.split("\\|")
      if (parts.length == 4) {
        Some(UploadMetadata(
          filename = parts(0).trim,
          contentType = parts(1).trim,
          size = parts(2).trim.toLong,
          checksum = parts(3).trim
        ))
      } else None
    }
  }

  private def processEntry(meta: UploadMetadata): Unit = {
    println(s"Processing: ${meta.filename}")
    var currentResult: Either[String, Path] = Right(Paths.get(UPLOAD_DIR, meta.filename))

    for ((stage, handler) <- processingChain) {
      currentResult match {
        case Right(_) =>
          currentResult = handler(meta)
          println(s"  [$stage] OK")
        case Left(err) =>
          println(s"  [$stage] SKIPPED (previous error: $err)")
      }
    }

    currentResult match {
      case Right(p) => println(s"  Completed: $p")
      case Left(e) => System.err.println(s"  Failed: $e")
    }
  }

  private def sanitizeFilename(filename: String): Either[String, String] = {
    // Strip any path components
    val baseName = Paths.get(filename).getFileName.toString
    ALLOWED_FILENAME_PATTERN.findFirstIn(baseName) match {
      case Some(safe) => Right(safe)
      case None => Left(s"Invalid filename characters: $baseName")
    }
  }

  private def validateUpload(meta: UploadMetadata): Either[String, Path] = {
    sanitizeFilename(meta.filename) match {
      case Left(err) => return Left(err)
      case Right(_) => // continue
    }
    val ext = getExtension(meta.filename)
    if (!ALLOWED_EXTENSIONS.contains(ext)) {
      return Left(s"Disallowed extension: $ext")
    }
    if (meta.size > MAX_FILE_SIZE) {
      return Left(s"File too large: ${meta.size}")
    }
    val targetPath = Paths.get(UPLOAD_DIR, meta.filename).normalize()
    // Ensure resolved path is within UPLOAD_DIR
    if (!targetPath.startsWith(Paths.get(UPLOAD_DIR))) {
      return Left("Path traversal detected")
    }
    if (!Files.exists(targetPath)) {
      return Left(s"File not found in staging: ${meta.filename}")
    }
    // Verify checksum integrity
    val actualChecksum = computeSHA256(targetPath.toFile)
    if (actualChecksum != meta.checksum) {
      return Left("Checksum mismatch")
    }
    Right(targetPath)
  }

  private def scanForMalware(meta: UploadMetadata): Either[String, Path] = {
    sanitizeFilename(meta.filename) match {
      case Left(err) => return Left(err)
      case Right(_) => // continue
    }
    val filePath = Paths.get(UPLOAD_DIR, meta.filename).normalize()
    if (!filePath.startsWith(Paths.get(UPLOAD_DIR))) {
      return Left("Path traversal detected")
    }
    val exitCode = invokeScanner(filePath)
    if (exitCode == 0) Right(filePath)
    else Left(s"Malware detected (exit code: $exitCode)")
  }

  private def invokeScanner(targetPath: Path): Int = {
    // Use ProcessBuilder with explicit argument array - no shell interpolation
    val pb = new ProcessBuilder("clamscan", "--no-summary", targetPath.toAbsolutePath.toString)
    Try {
      val process = pb.start()
      process.waitFor()
    } match {
      case Success(code) => code
      case Failure(_) => -1
    }
  }

  private def transformContent(meta: UploadMetadata): Either[String, Path] = {
    sanitizeFilename(meta.filename) match {
      case Left(err) => return Left(err)
      case Right(_) => // continue
    }
    val sourcePath = Paths.get(UPLOAD_DIR, meta.filename).normalize()
    val destPath = Paths.get(PROCESSED_DIR, meta.filename).normalize()
    if (!sourcePath.startsWith(Paths.get(UPLOAD_DIR)) || !destPath.startsWith(Paths.get(PROCESSED_DIR))) {
      return Left("Path traversal detected")
    }
    val ext = getExtension(meta.filename)

    ext match {
      case ".csv" => convertCsvToParquet(sourcePath, destPath)
      case ".json" => validateAndCopyJson(sourcePath, destPath)
      case ".xml" => transformXml(sourcePath, destPath)
      case ".txt" => copyPlainText(sourcePath, destPath)
      case _ => Left(s"No transformer for $ext")
    }
  }

  private def convertCsvToParquet(src: Path, dest: Path): Either[String, Path] = {
    // Use ProcessBuilder with explicit argument list - no shell interpolation
    val pb = new ProcessBuilder("csv2parquet", "--input", src.toAbsolutePath.toString, "--output", dest.toAbsolutePath.toString)
    val result = Try {
      val process = pb.start()
      process.waitFor()
    } match {
      case Success(0) => Right(dest)
      case Success(c) => Left(s"Conversion failed with code $c")
      case Failure(e) => Left(s"Conversion error: ${e.getMessage}")
    }
    result
  }

  private def validateAndCopyJson(src: Path, dest: Path): Either[String, Path] = {
    Try {
      val content = new String(Files.readAllBytes(src), "UTF-8")
      // Basic JSON validation - check balanced braces
      if (content.count(_ == '{') != content.count(_ == '}')) {
        throw new RuntimeException("Unbalanced JSON")
      }
      Files.copy(src, dest)
      dest
    } match {
      case Success(p) => Right(p)
      case Failure(e) => Left(e.getMessage)
    }
  }

  private def transformXml(src: Path, dest: Path): Either[String, Path] = {
    Try {
      Files.copy(src, dest)
      dest
    } match {
      case Success(p) => Right(p)
      case Failure(e) => Left(e.getMessage)
    }
  }

  private def copyPlainText(src: Path, dest: Path): Either[String, Path] = {
    Try {
      Files.copy(src, dest)
      dest
    } match {
      case Success(p) => Right(p)
      case Failure(e) => Left(e.getMessage)
    }
  }

  private def archiveProcessed(meta: UploadMetadata): Either[String, Path] = {
    sanitizeFilename(meta.filename) match {
      case Left(err) => return Left(err)
      case Right(_) => // continue
    }
    val processedPath = Paths.get(PROCESSED_DIR, meta.filename).normalize()
    if (!processedPath.startsWith(Paths.get(PROCESSED_DIR))) {
      return Left("Path traversal detected")
    }
    if (Files.exists(processedPath)) {
      val pb = new ProcessBuilder("gzip", processedPath.toAbsolutePath.toString)
      Try {
        val process = pb.start()
        process.waitFor()
      } match {
        case Success(0) => Right(Paths.get(processedPath.toString + ".gz"))
        case _ => Left("Archive failed")
      }
    } else {
      Left("Processed file not found for archiving")
    }
  }

  private def getExtension(filename: String): String = {
    val idx = filename.lastIndexOf('.')
    if (idx >= 0) filename.substring(idx).toLowerCase
    else ""
  }

  private def computeSHA256(file: File): String = {
    val digest = MessageDigest.getInstance("SHA-256")
    val bis = new BufferedInputStream(new FileInputStream(file))
    try {
      val buffer = new Array[Byte](8192)
      var bytesRead = bis.read(buffer)
      while (bytesRead != -1) {
        digest.update(buffer, 0, bytesRead)
        bytesRead = bis.read(buffer)
      }
      digest.digest().map("%02x".format(_)).mkString
    } finally {
      bis.close()
    }
  }
}
